-- Mod-authored era splash painting descriptions, pt_BR overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Nenhuma descrição para esta era."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Um grande templo com colunas se ergue no alto de um morro em terraços; salões menores com colunatas descem em degraus à sua direita. Jardins sobem a encosta abaixo deles, onde estreitas escadarias serpenteiam ao lado de um afloramento de rocha pálida coberto de ciprestes e arbustos floridos. Todo o mármore brilha em dourado quente ao sol."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Campos de trigo dourado se estendem abaixo de uma cidade murada de torres pálidas sobre uma colina. Bandeiras vermelhas pendem de suas ameias; a maior carrega um pássaro negro de asas abertas. É tempo de colheita: camponeses curvados recolhem o trigo ceifado, outros carregam altos feixes nas costas, e trabalhadores ao centro empilham uma carroça atrelada a um par de bois escuros. Árvores se inclinam para dentro pelos cantos superiores sob um céu suave e nebuloso."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Alto acima dos telhados de Florença, Michelangelo está de pé em uma escada de madeira, esculpindo o colossal Davi de mármore branco. A cabeça e os ombros da estátua sozinhos preenchem a esquerda do quadro; o escultor mal alcança seu ombro. Abaixo, telhados de telha vermelha se estendem até a grande cúpula da Catedral de Florença e um esguio campanário. Atrás deles, uma luz dourada rompe pelo céu escuro de tempestade."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Um barco a vapor vermelho e branco de pás cruza o Porto de Nova York no primeiro plano, soltando fumaça de duas chaminés negras. Passageiros alinham-se em seus dois conveses. Atrás dele, a Estátua da Liberdade se ergue verde contra um céu de âmbar nebuloso; mais navios navegam a vapor pela água além. Fumaça e névoa tingem toda a cena em sépia quente e dourado."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "O observador olha do alto de um arranha-céu para uma cidade cheia deles. Torres iluminadas recuam quarteirão após quarteirão em uma névoa dourada. Lá embaixo, vias expressas elevadas fazem curvas em um extenso entroncamento por onde carros e caminhões fluem ao longo das alças. Toda a pintura é de uma única cor, ouro e sépia como uma fotografia tingida."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Um sol baixo arde ao fundo de uma rua do centro do século XX, inundando-a de luz dourada. Homens de terno e chapéu fedora caminham pela calçada da direita de costas para o observador, passando por toldos e um grande letreiro iluminado. Sedas arredondadas e escuras estacionam ao longo do meio-fio ou passam. À frente, os edifícios se dissolvem no brilho."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Uma cidade futurista reluz ao longo de um litoral dourado, suas esguias torres recuando pela orla adentro da névoa. À esquerda, um elegante jato vermelho e branco inclina-se sobre a água; atrás dele uma ponte pênsil transpõe a baía. No primeiro plano à direita, um complexo de cúpula coroada em cromo e vidro está construído nas próprias falésias litorâneas. Vegetação margeia suas saliências; uma figura solitária se destaca em uma passarela."
